'use strict';
// 一次性差分等价验证（不属于仓库）：对旧/新 server 发同一请求序列，比对状态码与响应体。
const http = require('node:http');
const { spawn } = require('node:child_process');
const path = require('node:path');

const BOOT = `
  const http = require('node:http');
  const listen = http.Server.prototype.listen;
  http.Server.prototype.listen = function (...args) {
    const callback = typeof args.at(-1) === 'function' ? args.at(-1) : undefined;
    this.once('listening', () => process.send({ port: this.address().port }));
    return listen.call(this, { port: 0, host: '127.0.0.1' }, callback);
  };
  require(process.argv[1]);
`;

function startServer(file) {
  const child = spawn(process.execPath, ['-e', BOOT, file], {
    stdio: ['ignore', 'ignore', 'pipe', 'ipc'], env: { ...process.env, NODE_OPTIONS: '' },
  });
  let stderr = '';
  child.stderr.on('data', (d) => { stderr += d; });
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`startup timeout: ${stderr}`)), 3000);
    child.once('message', (m) => { clearTimeout(timer); resolve({ child, port: m.port }); });
    child.once('exit', () => reject(new Error('exited before readiness')));
  });
}

function request(port, method, body, urlPath) {
  return new Promise((resolve, reject) => {
    const req = http.request({ host: '127.0.0.1', port, path: urlPath, method, agent: false }, (res) => {
      let data = '';
      res.setEncoding('utf8');
      res.on('data', (c) => { data += c; if (data.length > 65536) res.destroy(new Error('too large')); });
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
      res.on('error', reject);
    });
    req.setTimeout(1500, () => req.destroy(new Error('timeout')));
    req.on('error', reject);
    req.end(body);
  });
}

// 同一请求序列：覆盖证明测试未触及的路径（空 body、null、原始类型、数组、超大/次正规数、404、PUT）。
const CASES = [
  ['GET', '/entries', undefined],
  ['POST', '/entries', ''],
  ['POST', '/entries', 'null'],
  ['POST', '/entries', 'true'],
  ['POST', '/entries', '123'],
  ['POST', '/entries', '"42"'],
  ['POST', '/entries', '[]'],
  ['POST', '/entries', '[1,2]'],
  ['POST', '/entries', '{}'],
  ['POST', '/entries', '{"amount":0}'],
  ['POST', '/entries', '{"amount":-1}'],
  ['POST', '/entries', '{"amount":"12"}'],
  ['POST', '/entries', '{"amount":null}'],
  ['POST', '/entries', '{"amount":1e400}'],
  ['POST', '/entries', '{"amount":1e999}'],
  ['POST', '/entries', '{"amount":5e-324}'],
  ['POST', '/entries', '{invalid'],
  ['POST', '/entries', '{"amount":'],
  ['POST', '/entries', '{"amount":}'],
  ['POST', '/entries', '{"amount":12,"note":"before"}'],
  ['POST', '/entries', '{"amount":12,"note":"before","extra":1}'],
  ['POST', '/entries', '{"amount":7,"note":"after"}'],
  ['POST', '/entries', '{"note":"no amount"}'],
  ['GET', '/entries', undefined],
  ['GET', '/nope', undefined],
  ['PUT', '/entries', '{}'],
  ['POST', '/other', '{}'],
  ['GET', '/entries', undefined],
];

function normalizeFinalGet(res) {
  // 末次 GET 剥离 ts 后比对；中间 GET 也走同一规则。
  try {
    const arr = JSON.parse(res.body);
    if (Array.isArray(arr)) {
      return { status: res.status, body: JSON.stringify(arr.map(({ ts, ...rest }) => ({ ...rest, tsFinite: Number.isFinite(ts) }))) };
    }
  } catch { /* 非 JSON 响应原样比对 */ }
  return res;
}

(async () => {
  const dir = __dirname;
  const oldSrv = await startServer(path.join(dir, 'old-server.cjs'));
  const newSrv = await startServer(path.resolve(dir, '../../private/var/folders/0v/f_smd31500113ppkqs66c9yr0000gn/T/skill-up-648527303/src/server.js'));
  let mismatch = 0;
  for (const [method, urlPath, body] of CASES) {
    const o = await request(oldSrv.port, method, body, urlPath);
    const n = await request(newSrv.port, method, body, urlPath);
    const on = normalizeFinalGet(o);
    const nn = normalizeFinalGet(n);
    const label = `${method} ${urlPath} ${body === undefined ? '(no body)' : JSON.stringify(body)}`;
    if (on.status !== nn.status || on.body !== nn.body) {
      mismatch += 1;
      console.log(`DIFF ${label}\n  old: ${on.status} ${JSON.stringify(on.body)}\n  new: ${nn.status} ${JSON.stringify(nn.body)}`);
    } else {
      console.log(`SAME ${label} -> ${on.status} ${on.body.length > 60 ? on.body.slice(0, 57) + '...' : on.body}`);
    }
  }
  console.log(mismatch === 0 ? `EQUIVALENT: ${CASES.length}/${CASES.length} cases identical` : `MISMATCH: ${mismatch} cases differ`);
  oldSrv.child.kill('SIGKILL');
  newSrv.child.kill('SIGKILL');
  process.exitCode = mismatch === 0 ? 0 : 1;
})().catch((e) => { console.error('ERROR', e); process.exitCode = 1; });

